prompt = FEW_SHOT + "Question: " + q + "\nAre follow up questions needed here:"
while True:
    out = llm(prompt, stop=["\nIntermediate answer:"])
    prompt += out
    if "So the final answer is:" in out:
        break
    follow_up = last_line(out).removeprefix("Follow up: ")
    answer = search(follow_up)
    prompt += "\nIntermediate answer: " + answer + "."
return after(prompt, "So the final answer is:")
